import { defineAsyncComponent } from "vue";
import type { DisplayModeRenderer } from "../display-mode-renderer";
import ChartSettings from "./ChartSettings.vue";

/**
 * Pass to `<YayawDataTable :display-mode-renderers="{ chart: chartRenderer }" />`
 * and list `"chart"` in `table.displayModes`. Unovis loads with the first
 * chart shown, not with the table.
 */
export const chartRenderer: DisplayModeRenderer = {
  view: defineAsyncComponent(() => import("./ChartView.vue")),
  settings: ChartSettings,
};

/* Unovis follows the host's shadcn tokens, light and dark, as the React chart does. */
:root {
  /* The host's shadcn chart palette wins; fallbacks are shadcn's neutral theme. */
  --yayaw-chart-1: var(--chart-1, oklch(0.646 0.222 41.116));
  --yayaw-chart-2: var(--chart-2, oklch(0.6 0.118 184.704));
  --yayaw-chart-3: var(--chart-3, oklch(0.398 0.07 227.392));
  --yayaw-chart-4: var(--chart-4, oklch(0.828 0.189 84.429));
  --yayaw-chart-5: var(--chart-5, oklch(0.769 0.188 70.08));
}
.dark {
  --yayaw-chart-1: var(--chart-1, oklch(0.488 0.243 264.376));
  --yayaw-chart-2: var(--chart-2, oklch(0.696 0.17 162.48));
  --yayaw-chart-3: var(--chart-3, oklch(0.769 0.188 70.08));
  --yayaw-chart-4: var(--chart-4, oklch(0.627 0.265 303.9));
  --yayaw-chart-5: var(--chart-5, oklch(0.645 0.246 16.439));
}
.yayaw-chart-view {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0.75rem;
  color: var(--yayaw-foreground);
  font-size: 0.875rem;
  line-height: 1.25rem;
}
.yayaw-chart-header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}
.yayaw-chart-header .yayaw-button {
  height: 2rem;
  gap: 0.375rem;
  font-size: 0.75rem;
  font-weight: 400;
}
.yayaw-chart-title {
  margin: 0;
  font-size: 0.875rem;
  font-weight: 500;
}
.yayaw-chart-message {
  display: block;
  color: var(--yayaw-muted-foreground);
  font-size: 0.875rem;
}
.yayaw-chart-error {
  color: var(--yayaw-danger);
}
.yayaw-chart-body {
  display: grid;
  /* Charts shrink with their container: Unovis sizes its SVG from it. */
  grid-template-columns: minmax(0, 1fr);
  gap: 0.75rem;
}
.yayaw-chart-loading {
  opacity: 0.6;
}
.yayaw-chart-canvas {
  --vis-font-family: inherit;
  --vis-axis-tick-label-color: var(--yayaw-muted-foreground);
  --vis-axis-tick-label-font-size: 12px;
  --vis-axis-grid-color: color-mix(
    in oklab,
    var(--yayaw-border) 60%,
    transparent
  );
  --vis-axis-domain-color: transparent;
  --vis-axis-tick-color: transparent;
  --vis-tooltip-background-color: var(--yayaw-background);
  --vis-tooltip-border-color: var(--yayaw-border);
  --vis-tooltip-text-color: var(--yayaw-foreground);
  --vis-tooltip-padding: 6px 10px;
  --vis-tooltip-border-radius: calc(var(--yayaw-radius) + 2px);
  --vis-crosshair-line-stroke-color: var(--yayaw-border);
  --vis-crosshair-circle-stroke-color: var(--yayaw-background);
  --vis-donut-central-label-text-color: var(--yayaw-foreground);
  --vis-donut-central-label-font-size: 24px;
  --vis-donut-central-label-font-weight: 600;
  --vis-donut-central-sub-label-text-color: var(--yayaw-muted-foreground);
  --vis-donut-central-sub-label-font-size: 12px;
  --vis-donut-background-color: var(--yayaw-muted);
  --vis-scatter-point-label-text-color-dark: var(--yayaw-foreground);
  --vis-scatter-point-label-text-color-light: var(--yayaw-foreground);
  --vis-scatter-point-label-text-font-size: 11px;
  --vis-xy-label-text-color-dark: var(--yayaw-foreground);
  --vis-xy-label-text-color-light: var(--yayaw-foreground);
  width: 100%;
}
.yayaw-chart-canvas[data-chart-clickable] :is(path, circle) {
  outline: none;
}
.yayaw-chart-tip {
  display: grid;
  min-width: 8rem;
  gap: 0.375rem;
  font-size: 0.75rem;
}
.yayaw-chart-tip-title {
  font-weight: 500;
}
.yayaw-chart-tip-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.yayaw-chart-tip-row strong {
  margin-left: auto;
  font-family: ui-monospace, monospace;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.yayaw-chart-swatch {
  display: inline-block;
  width: 0.625rem;
  height: 0.625rem;
  flex-shrink: 0;
  border-radius: 2px;
}
.yayaw-chart-muted {
  color: var(--yayaw-muted-foreground);
  font-variant-numeric: tabular-nums;
}
.yayaw-chart-legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.25rem 1rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 0.75rem;
}
.yayaw-chart-legend li {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}
.yayaw-chart-hint {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 0.75rem;
}
.yayaw-chart-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
}
.yayaw-chart-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.875rem;
}
.yayaw-chart-table thead {
  background: color-mix(in oklab, var(--yayaw-muted) 50%, transparent);
  color: var(--yayaw-muted-foreground);
  text-align: left;
}
.yayaw-chart-table th,
.yayaw-chart-table td {
  padding: 0.375rem 0.75rem;
}
.yayaw-chart-table thead th {
  padding-block: 0.5rem;
  font-weight: 500;
}
.yayaw-chart-table tbody tr {
  border-top: 1px solid var(--yayaw-border);
}
.yayaw-chart-table tbody th {
  font-weight: 400;
  text-align: left;
}
.yayaw-chart-number {
  text-align: right !important;
  font-variant-numeric: tabular-nums;
}
.yayaw-chart-strong {
  font-weight: 500;
}
.yayaw-chart-link {
  padding: 0;
  border: 0;
  background: none;
  color: var(--yayaw-foreground);
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 4px;
  cursor: pointer;
}
.yayaw-chart-link:focus-visible {
  outline: 2px solid var(--yayaw-ring);
  outline-offset: 2px;
  border-radius: 2px;
}
/* Number charts: the figure and what it counts, as in React. */
.yayaw-chart-figure {
  display: grid;
  place-items: center;
  gap: 0.25rem;
  padding: 3rem 0;
  text-align: center;
}
.yayaw-chart-figure-value {
  font-size: 3rem;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.025em;
  font-variant-numeric: tabular-nums;
}
/* Areas and combo charts: a click in a category's band shows its records. */
.yayaw-chart-band {
  position: relative;
}
.yayaw-chart-canvas[data-chart-clickable] .yayaw-chart-band {
  cursor: pointer;
}
/* A combo chart's second value axis, on the right, level with its ticks. */
.yayaw-chart-right-axis {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.yayaw-chart-right-axis span {
  position: absolute;
  right: 0;
  transform: translateY(-50%);
  color: var(--yayaw-muted-foreground);
  font-size: 12px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
/* Funnels: SVG shapes from the shared geometry, a button over each stage. */
.yayaw-chart-funnel {
  position: relative;
  width: 100%;
}
.yayaw-chart-funnel svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}
.yayaw-chart-funnel polygon {
  transition: opacity 150ms;
}
.yayaw-chart-funnel .yayaw-chart-funnel-dim {
  opacity: 0.5;
}
.yayaw-chart-funnel-name,
.yayaw-chart-funnel-value {
  fill: var(--yayaw-foreground);
  font-size: 12px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
}
.yayaw-chart-funnel-value {
  font-weight: 600;
}
.yayaw-chart-funnel-rate {
  fill: var(--yayaw-muted-foreground);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.yayaw-chart-funnel-button {
  position: absolute;
  padding: 0;
  border: 0;
  border-radius: calc(var(--yayaw-radius) + 2px);
  background: transparent;
  cursor: pointer;
  outline: none;
}
.yayaw-chart-funnel-button:hover {
  background: color-mix(in oklab, var(--yayaw-foreground) 5%, transparent);
}
.yayaw-chart-funnel-button:focus-visible {
  box-shadow: 0 0 0 2px var(--yayaw-ring);
}
/* The funnel's stage order in the settings panel. */
.yayaw-chart-stages {
  display: grid;
  gap: 0.375rem;
}
.yayaw-chart-stages-label {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 0.875rem;
}
.yayaw-chart-stages-list {
  display: grid;
  gap: 0.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}
.yayaw-chart-stage {
  display: flex;
  min-width: 0;
  min-height: 36px;
  align-items: center;
  gap: 4px;
  padding: 0 4px 0 6px;
  border: 1px solid var(--yayaw-border);
  border-radius: var(--yayaw-radius);
  background: var(--yayaw-background);
  font-size: 0.875rem;
}
.yayaw-chart-stage[data-drop-target] {
  border-color: var(--yayaw-primary, var(--yayaw-ring));
}
.yayaw-chart-stage[data-dragging] {
  opacity: 0.5;
}
.yayaw-chart-stage-grip {
  flex-shrink: 0;
  color: var(--yayaw-muted-foreground);
  cursor: grab;
  opacity: 0.6;
}
.yayaw-chart-stage-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-chart-stage .yayaw-chart-stage-move {
  width: 24px;
  min-width: 24px;
  height: 24px;
  min-height: 24px;
  padding: 0;
}
.yayaw-chart-stages-hint {
  margin: 0;
  color: var(--yayaw-muted-foreground);
  font-size: 0.75rem;
}
.yayaw-chart-stages-reset {
  justify-self: start;
  font-weight: 400;
}
/* `fill`: the chart takes its size container's height (a dashboard widget). */
.yayaw-chart-view.yayaw-chart-fill {
  display: flex;
  height: 100cqh;
  min-height: 0;
  flex-direction: column;
  gap: 0.5rem;
  overflow: hidden;
}
.yayaw-chart-fill-box {
  position: relative;
  min-height: 0;
  flex: 1;
}
.yayaw-chart-fill-content {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.yayaw-chart-fill-content[data-legend="right"] {
  flex-direction: row;
  align-items: center;
}
.yayaw-chart-fill-plot {
  min-width: 0;
}
.yayaw-chart-legend[data-placement="right"] {
  flex-direction: column;
  flex-shrink: 0;
  flex-wrap: nowrap;
  align-items: stretch;
  justify-content: center;
  gap: 0.25rem;
}
.yayaw-chart-legend[data-placement="right"] li {
  min-width: 0;
}
.yayaw-chart-legend[data-placement="right"] .yayaw-chart-legend-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.yayaw-chart-legend[data-placement="right"] .yayaw-chart-muted {
  margin-left: auto;
}
.yayaw-chart-canvas[data-small-donut] {
  --vis-donut-central-label-font-size: 16px;
}
.yayaw-chart-figure[data-fill] {
  height: 100%;
  align-content: center;
  padding: 0;
}
.yayaw-chart-figure[data-fill] .yayaw-chart-figure-value {
  font-size: 2.25rem;
}
